def solve_game(N):
    # dp[n] = True if n is a winning position (W, Type A), False if losing (L, Type B)
    # Since the game ends when N is reached, N-1 is the crucial state.
    # We define win/loss relative to the current player.
    # N is the goal. The player who moves to N wins.

    if N == 1:
        return True # A wins immediately

    dp = {}

    # Iterate backwards from N-1 down to 1
    for n in range(N - 1, 0, -1):
        # Check possible next moves: n+1 and 2n

        # 1. Check n+1
        move_plus_1 = False
        if n + 1 <= N:
            # If n+1 is a losing position for the *next* player, then n is a winning position.
            # Since we are moving backwards, dp[n+1] should already be calculated.
            if n + 1 == N:
                # If we move to N, we win. So this move leads to a Win state.
                move_plus_1 = True
            elif dp.get(n + 1) is False: # If n+1 is L (losing for the next player)
                move_plus_1 = True

        # 2. Check 2n
        move_times_2 = False
        if 2 * n <= N:
            if 2 * n == N:
                # If we move to N, we win.
                move_times_2 = True
            elif dp.get(2 * n) is False: # If 2n is L (losing for the next player)
                move_times_2 = True

        # n is a Winning position (True) if at least one move leads to an L position (or N)
        if move_plus_1 or move_times_2:
            dp[n] = True # W
        else:
            dp[n] = False # L

    # The game starts at 1.
    # If dp[1] is False, it is a Type B number.
    return dp.get(1, False)

