def solve_game(N):
    # DP[n] = True if the player whose turn it is at state n wins (Type A position)
    # DP[n] = False if the player whose turn it is at state n loses (Type B position)

    # We only need states from 1 up to N-1, as N is the winning state.
    dp = {} 

    # Iterate backwards from N-1 down to 1
    for n in range(N - 1, 0, -1):
        can_win = False

        # Check move n -> n+1
        if n + 1 == N:
            # Reaching N wins immediately
            can_win = True
        elif n + 1 < N:
            # Win if the opponent loses from n+1
            if not dp.get(n + 1, False): 
                # Note: dp.get(n+1, False) assumes uncalculated states are losing, 
                # but since we iterate backwards, n+1 must already be in dp 
                # unless N is very small (which it isn't here).
                can_win = True

        # Check move n -> 2n
        if not can_win and 2 * n <= N:
            if 2 * n == N:
                # Reaching N wins immediately
                can_win = True
            elif 2 * n < N:
                # Win if the opponent loses from 2n
                if not dp.get(2 * n, False):
                    can_win = True

        dp[n] = can_win

    return dp.get(1, False) # Returns True if starting at 1 is winning (Type A), False if losing (Type B)

