def solve_game(N):
    # dp[n] = 1 if position n is Winning (Type A for the current player)
    # dp[n] = 0 if position n is Losing (Type B for the current player)
    dp = [0] * (N + 1)

    # We iterate backwards from N-1 down to 1
    for n in range(N - 1, 0, -1):
        can_win = False

        # Check move to n+1
        if n + 1 <= N:
            if n + 1 == N:
                # Reaching N is an immediate win
                can_win = True
            elif dp[n + 1] == 0:
                # If n+1 is a Losing position for the next player, n is Winning
                can_win = True

        # Check move to 2n
        if not can_win and 2 * n <= N:
            if 2 * n == N:
                # Reaching N is an immediate win
                can_win = True
            elif dp[2 * n] == 0:
                # If 2n is a Losing position for the next player, n is Winning
                can_win = True

        dp[n] = 1 if can_win else 0

    return dp[1]

