def solve_game(N):
    # dp[i] is True if state i is a Winning (N) position for the current player, False if Losing (P) position.
    # We are interested in dp[1].
    dp = {}

    # Terminal state N: Reaching N wins. 
    # States that can reach N in one step are Winning.

    # Initialize all states up to N.
    for i in range(1, N + 1):
        dp[i] = None

    # We iterate backwards from N-1 down to 1.
    for n in range(N - 1, 0, -1):
        can_win = False

        # Check move n+1
        next_n_plus_1 = n + 1
        if next_n_plus_1 <= N:
            if next_n_plus_1 == N:
                # Direct win
                can_win = True
            elif dp[next_n_plus_1] is False:
                # Move to a losing position for the opponent
                can_win = True

        # Check move 2n
        next_2n = 2 * n
        if next_2n <= N:
            if next_2n == N:
                # Direct win
                can_win = True
            elif dp[next_2n] is False:
                # Move to a losing position for the opponent
                can_win = True

        # If neither move guarantees a win, then n is a losing position.
        if not can_win:
            # If all legal moves lead to a winning position for the opponent, n is losing.
            is_losing = True

            # Check n+1
            if n + 1 <= N:
                if dp[n + 1] is False:
                    is_losing = False

            # Check 2n
            if 2 * n <= N:
                if dp[2 * n] is False:
                    is_losing = False

            dp[n] = not is_losing
        else:
            dp[n] = True

    # Note: The standard definition of P/N positions applies. 
    # If dp[1] is False, starting at 1 is a Losing (P) position, meaning Player B wins.
    return "Type B" if dp[1] == False else "Type A"

