def solve_game(N):
    # DP[n] is True if position n is a Winning position (Type A move from n).
    # DP[n] is False if position n is a Losing position (Type B move from n).
    # We consider the state *before* a number is written.
    # We need to know if the starting position 1 is Type A or Type B.
    # In this game, reaching N is an immediate win.

    DP = {}

    # Since the game ends at N (the winner is the one who reaches N),
    # positions leading directly to N are winning.

    for n in range(1, N + 1):
        # Base case: If n = N, the game is already over, but we define the state prior to N.
        if n == N:
            continue

        can_win = False

        # Check move n+1
        if n + 1 <= N:
            if n + 1 == N:
                can_win = True # Immediate win
            elif not DP.get(n + 1, True): # If n+1 is a Losing position (False) for the opponent
                can_win = True

        if can_win:
            DP[n] = True
            continue

        # Check move 2n
        if 2 * n <= N:
            if 2 * n == N:
                can_win = True # Immediate win
            elif not DP.get(2 * n, True): # If 2n is a Losing position (False) for the opponent
                can_win = True

        DP[n] = can_win

    # The function should calculate the classification of the starting position 1.
    # Type A if DP[1] is True, Type B if DP[1] is False.
    if DP.get(1, False):
        return "Type A"
    else:
        return "Type B"

